# -*- coding: utf-8 -*-
S = "контрольная выборка №4 (ручной разбор 30.09), проверено вычислением; условия сверены с учебниками Виленкина 6 и Мерзляк/Макарычев по OCR, где они есть"
P = {}
def E(t, why, **kw): P[t] = dict(src=S, why=why, **kw)

PERM = "ключ (и часть неверных вариантов) принадлежали соседнему пункту упражнения — при импорте ключи и условия пунктов были перепутаны; условие сохранено, ключ и варианты пересчитаны вручную"
EQ = "Ученик привёл дроби к общему знаменателю, но сравнил только знаменатели и знаки (они совпадают) и сделал вывод о равенстве, не сравнив числители."
EQ2 = "Ученик решил, что раз знаки «минус» одинаковы, а разница мала, числа равны, и не сравнил их точно."
MOD = "Ученик сравнил модули чисел, не учтя, что из двух отрицательных чисел больше то, у которого модуль меньше."

# --- Виленкин 6, № 1010 (сравнение отрицательных чисел): ключи переставлены попарно
E("G6_TB_25_1010.2", PERM, k=r"$-\dfrac{2}{9} > -\dfrac{5}{9}$")
E("G6_TB_25_1010.3", PERM, k=r"$-3{,}11 < -3{,}1$", drop=[0, 1],
  dadd=[(r"$-3{,}11 > -3{,}1$", "Ученик сравнил модули как обычные десятичные дроби ($3{,}11 > 3{,}1$) и не изменил знак неравенства для отрицательных чисел."),
        (r"$-3{,}11 = -3{,}1$", "Ученик отбросил последний разряд и решил, что $-3{,}11$ и $-3{,}1$ равны.")])
E("G6_TB_25_1010.4", PERM, k=r"$-45 < -20$", drop=[0, 1],
  dadd=[(r"$-45 > -20$", MOD), (r"$-45 = -20$", "Ученик решил, что числа с одинаковым знаком «минус» равны, не сравнив их модули.")])
E("G6_TB_25_1010.6", PERM, k=r"$-\dfrac{5}{12} > -\dfrac{11}{18}$", drop=[0, 1],
  dadd=[(r"$-\dfrac{5}{12} < -\dfrac{11}{18}$", r"Ученик привёл дроби к знаменателю $36$ ($\dfrac{15}{36}<\dfrac{22}{36}$) и перенёс этот знак на отрицательные числа, не изменив его на противоположный."),
        (r"$-\dfrac{5}{12} = -\dfrac{11}{18}$", EQ)])
E("G6_TB_25_1010.7", PERM, k=r"$-68 < 0$")
E("G6_TB_25_1010.8", PERM, k=r"$-\dfrac{3}{5} < -\dfrac{8}{15}$", drop=[1, 2],
  dadd=[(r"$-\dfrac{3}{5} = -\dfrac{8}{15}$", EQ)])

# --- Виленкин 5, № 1200 (сравнение десятичных дробей)
E("G5_TB_32_1200.2", PERM, k=r"$7{,}299 < 7{,}3$", drop=[0, 1],
  dadd=[(r"$7{,}299 > 7{,}3$", "Ученик сравнил дробные части как целые числа ($299 > 3$) и не учёл разрядность десятичных дробей."),
        (r"$7{,}299 = 7{,}3$", "Ученик округлил $7{,}299$ до $7{,}3$ и решил, что числа равны.")])
E("G5_TB_32_1200.3", PERM, k=r"$3{,}29 < 3{,}3$",
  dnew={0: (r"$3{,}29 > 3{,}3$", "Ученик сравнил дробные части как целые числа ($29 > 3$) и не учёл, что $3{,}3 = 3{,}30$.")})
E("G5_TB_32_1200.4", PERM, k=r"$8{,}605 > 8{,}59$", drop=[1, 2],
  dadd=[(r"$8{,}605 = 8{,}59$", "Ученик решил, что числа отличаются только записью и потому равны.")])
E("G5_TB_32_1200.5", PERM, k=r"$6{,}504 < 6{,}505$", drop=[1],
  dnew={0: (r"$6{,}504 > 6{,}505$", "Ученик решил, что в разряде тысячных большая цифра даёт меньшее число, и перепутал знак сравнения.")})

# --- Виленкин 6, № 395 (степени): ключи переставлены
E("G7_TB_18_395.2", PERM, k=r"$(-5{,}9)^{3} < (-5{,}9)^{2}$")
