# --- Виленкин 6, № 978: условия пунктов г), ж), б), з) были искажены («−2 2/5» → «−2: 2/5»), ключи перепутаны; по учебнику:
# а) −2/15 и 3/4; б) 3 и −2/3; в) −3/4 и −4/5; г) −2 2/5 и 3 3/7; д) −7/10 и −3/8; е) −5/6 и −11/24; ж) −2 2/7 и −5/7; з) −5 5/14 и −5 8/21
Q978 = "Сравните числа и результат запишите в виде неравенства: "
W978 = "условие пункта восстановлено по учебнику (Виленкин, 6 кл., № 978: смешанные числа и «3 и −2/3» были искажены при импорте); ключ и варианты пересчитаны — прежний ключ принадлежал другому пункту"
E("G6_TB_24_978.2", W978, q=Q978 + r"$-2\dfrac{2}{5}$ и $3\dfrac{3}{7}$", k=r"$-2\dfrac{2}{5} < 3\dfrac{3}{7}$",
  dnew={1: (r"$-2\dfrac{2}{5} = 3\dfrac{3}{7}$", "Ученик решил, что числа равны по модулю или не сравнил отрицательное и положительное число.")})
E("G6_TB_24_978.3", W978, q=Q978 + r"$-2\dfrac{2}{7}$ и $-\dfrac{5}{7}$", k=r"$-2\dfrac{2}{7} < -\dfrac{5}{7}$", drop=[0, 1, 2],
  dadd=[(r"$-2\dfrac{2}{7} > -\dfrac{5}{7}$", "Ученик сравнил дробные части ($\\dfrac{2}{7} < \\dfrac{5}{7}$), не заметив целой части $2$, и решил, что $-2\\dfrac{2}{7}$ больше."),
        (r"$-2\dfrac{2}{7} = -\dfrac{5}{7}$", "Ученик решил, что у чисел одинаковые знаменатели и знаки, значит, они равны."),
        (r"$-\dfrac{2}{7} > -\dfrac{5}{7}$", "Ученик потерял целую часть $2$ и сравнил $-\\dfrac{2}{7}$ с $-\\dfrac{5}{7}$.")])
E("G6_TB_24_978.4", W978, q=Q978 + r"$3$ и $-\dfrac{2}{3}$", k=r"$3 > -\dfrac{2}{3}$",
  dnew={0: (r"$3 = -\dfrac{2}{3}$", "Ученик сравнил модули и решил, что числа равны, не учтя знак и величину.")})
E("G6_TB_24_978.6", W978, q=Q978 + r"$-5\dfrac{5}{14}$ и $-5\dfrac{8}{21}$", k=r"$-5\dfrac{5}{14} > -5\dfrac{8}{21}$", drop=[2],
  dnew={1: (r"$-5\dfrac{5}{14} = -5\dfrac{8}{21}$", "Ученик решил, что у чисел одинаковые целые части и знаки, значит, они равны.")})
E("G6_TB_24_978.8", PERM, k=r"$-\dfrac{5}{6} < -\dfrac{11}{24}$",
  dnew={0: (r"$-\dfrac{5}{6} > -\dfrac{11}{24}$", MOD), 1: (r"$-\dfrac{5}{6} = -\dfrac{11}{24}$", EQ)})

