E("G6_TB_7_311", "в неверном варианте пункт а) содержал внутреннее противоречие «(4 мин < 10 мин)»; по описанию ошибки (сравнение числителей $4$ и $3$) должно быть «$4$ мин $>$ $3$ мин»",
  dval={1: r"а) $\dfrac{4}{15}$ ч $>$ $\dfrac{3}{10}$ ч ($4$ мин $>$ $3$ мин); б) $\dfrac{7}{20}$ ч $<$ $\dfrac{11}{30}$ ч ($7$ мин $<$ $11$ мин); в) $\dfrac{3}{5}$ ч $>$ $\dfrac{2}{3}$ ч ($3$ мин $>$ $2$ мин); г) $\dfrac{5}{12}$ ч $<$ $\dfrac{8}{15}$ ч ($5$ мин $<$ $8$ мин)"})
E("G6_TB_30_1169.2", "объяснения неверных вариантов были бессмысленными (разорванные десятичные дроби, противоречивая логика); вариант $2{,}35$ не выводился из ошибки — заменён на $8{,}8$ ($s/t$ без вычитания $b$); проверено: $a=s/t-b=8{,}8-3{,}2=5{,}6$",
  dnew={0: (r"$12$", r"Ученик нашёл $s:t=2{,}2:\dfrac{1}{4}=8{,}8$, но вместо вычитания скорости Веры прибавил её: $8{,}8+3{,}2=12$."),
        1: (r"$8{,}8$", r"Ученик нашёл общую скорость удаления $s:t=8{,}8$ км/ч и забыл вычесть скорость Веры $b=3{,}2$ км/ч."),
        2: (r"$-2{,}65$", r"Ученик умножил $s$ на $\dfrac{1}{4}$ вместо деления: $2{,}2\cdot0{,}25-3{,}2=-2{,}65$.")})
E("GEN_G6_S45_01_C_02", "объяснения неверных вариантов $-7$ и $17$ были самопротиворечивыми; переписаны по реальному способу получения значений; проверено: $M(-12;-7)$, $K(-12;0)$, сумма $-12$",
  dnew={0: (r"$-7$", r"Ученик нашёл ординату точки $M(-12;\,-7)$ и записал её вместо суммы координат точки $K(-12;\,0)$."),
        1: (r"$17$", r"Ученик забыл знак «минус» у абсциссы: $M(12;\,17)$ — и записал ординату $17$ вместо суммы координат точки $K$.")})
